    - { choose: 2, from: ["Literacy: Other"], bonus: 66, note: "Literacy: Other twice over, the written half of those two languages - +66 on its own 30%, for the 96% printed 161 gives." }
    - { choose: 1, from: ["Automobile", "Motorcycles & Snowmobiles"], note: "Printed 161: pilot automobile OR motorcycle, at 96%. Taken from this list the pick starts at its catalog base, which is 60 for both." }
    - { choose: 7, from: ["Chemistry", "Chemistry ' || char(8212) || ' Analytical", "Forensics", "Cryptography", "Disguise", "Forgery", "Intelligence", "Interrogation", "Impersonation", "Paramedic", "Pathology", "Pick Locks", "Surveillance", "Basic Electronics"], note: "Printed 161: seven from the list of skills that apply to detective work. The book prints a different one-time bonus beside each - Chemistry, Criminal Sciences/Forensics, Cryptography and Surveillance Systems at +30%, Chemistry: Analytical, Interrogation and Paramedic at +25%, Impersonation at +30%, Disguise at +25%, Basic Electronics at +25%, Pathology at +25%, Intelligence at +20%, Pick Locks at +20%, Forgery at +10% - and a `from` list grants each pick at its catalog base. The figures are in the body." }
  secondary_skills: { count: 8 }
